SELECT FROM cut_cutover_configuration_revision WHERE configuration_code = #{query.configurationCode} AND deleted = b'0'
AND status_code = #{query.statusCode}
ORDER BY revision_no DESC LIMIT 1

SELECT 
FROM cut_cutover_configuration_revision
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.configurationRevisionId}
  AND configuration_code = #{query.configurationCode}
  AND revision_no = #{query.configurationRevisionNo}
  AND deleted = b'0'

SELECT 
FROM cut_cutover_configuration_revision
WHERE tenant_id = #{query.tenantId}
  AND configuration_code = #{query.configurationCode}
  AND status_code = 'PUBLISHED'
  AND effective_start_time <= #{query.taskCreatedAt}
  AND (effective_end_time IS NULL OR effective_end_time > #{query.taskCreatedAt})
  AND deleted = b'0'
